def transform(grid):
    h, w = len(grid), len(grid[0])
    axes = [
        lambda r, c: r,
        lambda r, c: c,
        lambda r, c: c - r,
        lambda r, c: r + c,
    ]

    best_axis = 0
    best_errors = None
    for i, key_fn in enumerate(axes):
        groups = {}
        total = 0
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v:
                    k = key_fn(r, c)
                    groups.setdefault(k, {}).setdefault(v, 0)
                    groups[k][v] += 1
                    total += 1
        errors = total - sum(max(counts.values()) for counts in groups.values())
        if best_errors is None or errors < best_errors:
            best_axis, best_errors = i, errors

    key_fn = axes[best_axis]
    groups = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                groups.setdefault(key_fn(r, c), {})
                groups[key_fn(r, c)][v] = groups[key_fn(r, c)].get(v, 0) + 1

    labels = {k: max(counts, key=counts.get) for k, counts in groups.items()}
    keys = list(labels)
    period = max(h, w) * 2 + 1
    for p in range(1, max(h + w + 1, 2)):
        residues = {}
        valid = True
        for k, v in labels.items():
            r = k % p
            if r in residues and residues[r] != v:
                valid = False
                break
            residues[r] = v
        if valid:
            period = p
            break

    residue_colors = {}
    for k, v in labels.items():
        residue_colors[k % period] = v

    def color_for(k):
        residue = k % period
        if residue in residue_colors:
            return residue_colors[residue]
        nearest = min(
            residue_colors,
            key=lambda x: min((residue - x) % period, (x - residue) % period)
        )
        return residue_colors[nearest]

    return [
        [color_for(key_fn(r, c)) for c in range(w)]
        for r in range(h)
    ]
